import {reliefJournal} from './cossenne-services.js?v=0.90.52';
import {orchardNextStep} from './orchard-guidance.js?v=0.90.52';
import {claimChoiceReward,choiceRewardText} from './choice-rewards.js?v=0.90.52';
import {ORCHARD_ROUTES,COSSENNE_CACHES} from './cossenne-data.js?v=0.90.52';
export const cossenneUnlocked=s=>['SPARED','EXECUTED'].includes(s.fates?.['LDR-03']);
export function cossenneState(s){s.cossenne??={};const q=s.cossenne;q.version=1;q.walk??=[];q.valves??=[];q.events??=[];q.expeditions??={};return q;}
export function cossenneEvent(s,id){const q=cossenneState(s);if(q.events.includes(id))return false;q.events.push(id);s.storyFlags??={};if(id==='CH05-E01')s.storyFlags.rhoswen_arc_state=Math.max(1,s.storyFlags.rhoswen_arc_state||0);if(id==='CH05-E03')s.storyFlags.religious_parallels_found=(s.storyFlags.religious_parallels_found||0)+2;if(id==='CH05-O01')s.storyFlags.two_prayers_unlocked=true;if(id==='CH05-E06')s.storyFlags.kurg_doubt_state=1;return true;}
export function cossenneWalk(s,id){if(!cossenneUnlocked(s)||!['farmer','child','carer','shrine'].includes(id))return false;const q=cossenneState(s);if(q.walk.includes(id))return false;q.walk.push(id);if(id==='carer')s.cossenneClues=true;if(id==='shrine')cossenneEvent(s,'CH05-E03');if(cossenneReady(s))cossenneEvent(s,'CH05-E02');return true;}
export function cossenneReady(s){return cossenneUnlocked(s)&&['farmer','child','carer','shrine'].every(id=>s.cossenne?.walk?.includes(id));}
export function settleCossenneFate(s,fate){if(!['SPARED','EXECUTED'].includes(fate)||s.fates?.['LDR-04']||!s.defeatedTrainers?.includes('LDR-04'))return false;s.fates??={};s.fates['LDR-04']=fate;s.pendingFate=null;s.storyFlags??={};s.storyFlags.leader_04_spared=fate==='SPARED';s.storyFlags.occupation_cossenne=fate==='SPARED'?'supervised_mediation':'quiet_mourning';cossenneEvent(s,'CH05-E04');cossenneEvent(s,'CH05-E05');return true;}
export function acceptCossenneWater(s){const q=cossenneState(s);if(!cossenneUnlocked(s)||q.waterAccepted)return false;q.waterAccepted=true;return true;}
export function cossenneValve(s,id){const q=cossenneState(s);if(!cossenneUnlocked(s)||!q.waterAccepted||!['west','east'].includes(id)||q.valves.includes(id))return false;q.valves.push(id);return true;}
export function finishCossenneWater(s){const q=cossenneState(s);if(q.waterDone||q.valves.length!==2)return false;q.waterDone=true;s.money=(s.money||0)+900;s.poultices=(s.poultices||0)+3;return true;}
export function expeditionState(s,key){if(!['grove','shrine'].includes(key))return null;return cossenneState(s).expeditions[key]??={accepted:false,records:[],rings:[0,0,0],solved:false,choice:null,claimed:false};}
export function acceptOrchardExpedition(s,key){const q=expeditionState(s,key);if(!cossenneUnlocked(s)||!q||q.accepted)return false;q.accepted=true;return true;}
export function orchardPassage(s,key,stage){const q=expeditionState(s,key);return !!q?.accepted&&q.records.includes(stage)&&(stage!==1||q.solved);}
export function orchardRecord(s,key,stage){const q=expeditionState(s,key);if(!q?.accepted||!Number.isInteger(stage)||stage<0||stage>2||q.records.includes(stage)||stage>0&&!orchardPassage(s,key,stage-1))return false;q.records.push(stage);return true;}
export const ORCHARD_TARGETS={grove:[2,1,3],shrine:[3,2,1]};
export function orchardControl(s,key,index,reset=false){const q=expeditionState(s,key);if(!q?.accepted||!q.records.includes(1)||q.solved||!Number.isInteger(index)||index<0||index>2)return false;if(reset){q.rings=[0,0,0];return true;}q.rings[index]=(q.rings[index]+1)%4;q.solved=q.rings.every((n,i)=>n===ORCHARD_TARGETS[key][i]);return true;}
export function orchardAssist(s,key){const q=expeditionState(s,key),type=key==='grove'?'GRASS':'WATER';if(!q?.accepted||!q.records.includes(1)||q.solved||!s.party?.some(u=>u.hp>0&&!u.dead&&u.species?.types?.includes(type)))return false;q.rings=[...ORCHARD_TARGETS[key]];q.solved=true;return true;}
export function orchardChoice(s,key,choice){const q=expeditionState(s,key),guard=key==='grove'?'TRN-C05-005':'TRN-C05-007';if(!q?.accepted||q.choice||!q.solved||q.records.length!==3||!s.defeatedTrainers?.includes(guard)||!['a','b'].includes(choice))return false;q.choice=choice;s.storyChoices??={};s.storyChoices['orchard_'+key]=choice;return true;}
export function claimOrchardExpedition(s,key){const q=expeditionState(s,key);if(!q?.choice||q.claimed)return false;q.claimed=true;s.money=(s.money||0)+1200;s.trainingTonics=(s.trainingTonics||0)+(key==='grove'?3:2);if(key==='grove')q.keepsake='Pilgrim Bell';else s.emergencyEvacs=(s.emergencyEvacs||0)+2;claimChoiceReward(s,'orchard_'+key,q.choice);return true;}
export function claimOrchardCache(s,id){if(!cossenneUnlocked(s)||!COSSENNE_CACHES[id]||s.supplyClaims?.includes(id))return false;if(id==='ow-grove-cache'&&!s.defeatedTrainers?.includes('TRN-C05-005')||id==='ow-shrine-cache'&&!s.defeatedTrainers?.includes('TRN-C05-007'))return false;s.supplyClaims??=[];s.supplyClaims.push(id);for(const [k,n]of Object.entries(COSSENNE_CACHES[id]))s[k]=(s[k]||0)+n;return true;}
export function cossenneObjective(s,room){const q=cossenneState(s),r=ORCHARD_ROUTES[room];if(r){const key=room.startsWith('pilgrimGrove')?'grove':room.startsWith('sunkenShrine')?'shrine':null;if(key){const stage=Number(room.at(-1))?Number(room.at(-1))-1:0,p=expeditionState(s,key),guard=key==='grove'?'TRN-C05-005':'TRN-C05-007';return {spot:!p.accepted?'ow-'+key+'-keeper':p.choice&&!p.claimed?(stage===0?'ow-'+key+'-keeper':room+'-back'):!p.records.includes(stage)?'ow-'+key+'-record-'+stage:stage===1&&!p.solved?'ow-'+key+'-control-0':stage===2&&!s.defeatedTrainers?.includes(guard)?guard:stage===2&&!p.choice?'ow-'+key+'-resolution':stage<2&&!p.choice?room+'-forward':room+'-back',text:orchardNextStep(s,key)};}return {spot:room+'-forward',text:'Follow the cleared forest road to Cossenne'};}if(room==='cossenneFarm')return {spot:q.walk.includes('farmer')?'cs-farm-home':'cs-farmer',text:q.walk.includes('farmer')?'Explore the working pasture and field, then return to the market':'Speak to Khadija beside the working field'};if(room==='cossenne'){const next=['farmer','child','carer','shrine'].find(id=>!q.walk.includes(id));return {spot:next?(next==='farmer'?'cs-farm-entry':'cs-'+next):!s.fates?.['LDR-04']?'cossenne-fort-entry':'cs-boundary',text:next?{farmer:'Meet Khadija through the communal farm gate north of town',child:'Meet the child beside the working partners',carer:'Ask the carer about Pate and Trade',shrine:'Hear the account at the shrine'}[next]:!s.fates?.['LDR-04']?'Enter the shrine fort and hear Warden Ismail':'Explore Cossenne; Marasen is the next chapter'};}return null;}
export function cossenneJournal(s,room){if(!ORCHARD_ROUTES[room]&&!room?.startsWith('cossenne'))return null;const q=cossenneState(s);return 'Cossenne · Valley walk '+q.walk.length+'/4. '+(q.waterDone?'Reservoir channels restored.':q.waterAccepted?'Reservoir: army tank-filling closed the valves and left the fire ditch dry. Open '+(['west','east'].filter(k=>!q.valves.includes(k)).join(' and ')||'no further')+' valves inside Cossenne, then report to Ali by the eastern reservoir for 900 doubloons and three Poultices.':'Ask Waterkeeper Ali at the eastern reservoir about the dry fire ditch.')+' '+['grove','shrine'].map(key=>orchardNextStep(s,key)).join(' ')+' '+reliefJournal(s);}
